const MCP_HOST_AUTHZ_COOKIE = "mcp_host_authz";

export type McpOauthResourceProfile = {
  resourceUri?: (baseUrl: string) => string;
  defaultScopes: readonly string[];
  scopesSupported: (input: string | readonly string[]) => boolean;
  employeeOnly?: boolean;
  consentActionPath?: string;
  jwtAccessTokens?: boolean;
  endpoints?: typeof mcpHostOAuthEndpoints;
};

const defaultProfile: McpOauthResourceProfile = {
  resourceUri: mcpHostResourceUri,
  defaultScopes: MCP_HOST_DEFAULT_SCOPES,
  scopesSupported: areMcpHostScopesSupported,
};

function genesisCloudOrgId(): string {
  return process.env.AGENTUITY_CLOUD_ORG_ID?.trim() || process.env.AGENTUITY_ORG_ID?.trim() || "";
}

function setPendingAuthorizationCookie(c: Context<Env>, pending: PendingAuthorization): void {
  setCookie(c, MCP_HOST_AUTHZ_COOKIE, encodePendingAuthorization(pending), {
    httpOnly: true,
    secure: c.req.url.startsWith("https:"),
    sameSite: "Lax",
    path: "/",
    maxAge: MCP_HOST_AUTHORIZATION_CODE_TTL_SECONDS,
  });
}

export function redirectWithOAuthError(
  redirectUri: string,
  error: string,
  issuer: string,
  state?: string,
): string {
  const url = new URL(redirectUri);
  url.searchParams.set("error", error);
  url.searchParams.set("iss", issuer);
  if (state) url.searchParams.set("state", state);
  return url.toString();
}

export function redirectWithCode(
  redirectUri: string,
  code: string,
  issuer: string,
  state?: string,
): string {
  const url = new URL(redirectUri);
  url.searchParams.set("code", code);
  url.searchParams.set("iss", issuer);
  if (state) url.searchParams.set("state", state);
  return url.toString();
}

export async function handleMcpHostOauthAuthorize(
  c: Context<Env>,
  user: AuthUser | null,
  profile: McpOauthResourceProfile = defaultProfile,
) {
  const endpoints = (profile.endpoints ?? mcpHostOAuthEndpoints)(c);
  const query = c.req.query();
  const responseType = query.response_type?.trim();
  const clientId = query.client_id?.trim();
  const redirectUri = query.redirect_uri?.trim();
  const state = query.state?.trim();
  const codeChallenge = query.code_challenge?.trim();
  const codeChallengeMethod = query.code_challenge_method?.trim() || "S256";
  const resource = query.resource?.trim() || profile.resourceUri?.(mcpHostApiBaseUrl(c));
  const requestedScopes = query.scope ?? profile.defaultScopes.join(" ");
  const scopes = normalizeMcpHostScopes(requestedScopes);

  if (responseType !== "code") {
    return c.text("unsupported_response_type", 400);
  }
  if (!clientId || !redirectUri || !codeChallenge || !resource || codeChallengeMethod !== "S256") {
    return c.text("invalid_request", 400);
  }

  const pending: PendingAuthorization = {
    clientId,
    redirectUri,
    scopes,
    state,
    codeChallenge,
    codeChallengeMethod,
    resource,
  };

  if (!user) {
    setPendingAuthorizationCookie(c, pending);
    const returnTo = `${endpoints.authorizationEndpoint}?${new URL(c.req.url).searchParams.toString()}`;
    return c.redirect(`/api/auth/login?returnTo=${encodeURIComponent(returnTo)}`);
  }

  let client: ResolvedMcpHostOauthClient | null;
  try {
    client = await resolveMcpHostOauthClient(clientId);
  } catch (error) {
    c.var.logger.warn("[mcp-host] Failed to resolve OAuth client metadata", {
      clientId,
      error: error instanceof Error ? error.message : String(error),
    });
    return c.text("invalid_client", 400);
  }
  if (!client || !mcpHostRedirectUriMatches(client.redirectUris, redirectUri)) {
    return c.text("invalid_client", 400);
  }
  if (!profile.scopesSupported(requestedScopes)) {
    return c.redirect(
      redirectWithOAuthError(redirectUri, "invalid_scope", endpoints.issuer, state),
    );
  }
  if (profile.employeeOnly && !isInternalAgentuityEmail(user.email)) {
    return c.redirect(
      redirectWithOAuthError(redirectUri, "access_denied", endpoints.issuer, state),
    );
  }

  setPendingAuthorizationCookie(
    c,
    parseMcpClientIdMetadataUrl(clientId)
      ? { ...pending, clientMetadataDigest: mcpHostOauthClientMetadataDigest(client) }
      : pending,
  );
  // Prefer the user's Genesis memberships; optional preferred id from deployment env.
  const orgDisplayName = await resolveCurrentOrgDisplayName(user.id, genesisCloudOrgId(), {
    onError: (error) =>
      c.var.logger.warn("[mcp-host] Failed to load org name for consent page", {
        genesisUserId: user.id,
        error: error instanceof Error ? error.message : String(error),
      }),
  });
  return c.html(
    renderMcpHostConsentPage({
      clientName: client.clientName,
      clientLogoUri: client.logoUri,
      redirectUri,
      scopes,
      userDisplayName: user.name ?? null,
      userEmail: user.email,
      userImage: user.image ?? null,
      orgDisplayName,
      consentActionPath: profile.consentActionPath,
    }),
  );
}

export async function handleMcpHostOauthConsent(
  c: Context<Env>,
  user: AuthUser,
  profile: McpOauthResourceProfile = defaultProfile,
) {
  const pending = decodePendingAuthorization(getCookie(c, MCP_HOST_AUTHZ_COOKIE));
  deleteCookie(c, MCP_HOST_AUTHZ_COOKIE, { path: "/" });

  const body = await c.req.parseBody();
  const decisionValue = typeof body.decision === "string" ? body.decision : "";

  if (!pending) {
    return c.html(renderMcpHostConsentExpiredPage(), 400);
  }
  if (profile.employeeOnly && !isInternalAgentuityEmail(user.email)) {
    return c.html(renderMcpHostConsentExpiredPage(), 403);
  }

  let client: ResolvedMcpHostOauthClient | null;
  try {
    client = await resolveMcpHostOauthClient(pending.clientId);
  } catch {
    client = null;
  }
  if (!client || !mcpHostRedirectUriMatches(client.redirectUris, pending.redirectUri)) {
    return c.html(renderMcpHostConsentExpiredPage(), 400);
  }

  if (decisionValue === "deny") {
    return c.redirect(
      redirectWithOAuthError(
        pending.redirectUri,
        "access_denied",
        (profile.endpoints ?? mcpHostOAuthEndpoints)(c).issuer,
        pending.state,
      ),
    );
  }
  if (decisionValue !== "approve") {
    return c.text("invalid_request", 400);
  }
  const expectedResource = profile.resourceUri?.(mcpHostApiBaseUrl(c));
  if (pending.resource !== expectedResource) {
    return c.html(renderMcpHostConsentExpiredPage(), 400);
  }
  if (pending.codeChallengeMethod !== "S256" || !pending.codeChallenge.trim()) {
    return c.text("invalid_request", 400);
  }

  if (parseMcpClientIdMetadataUrl(pending.clientId)) {
    if (
      !pending.clientMetadataDigest ||
      mcpHostOauthClientMetadataDigest(client) !== pending.clientMetadataDigest
    ) {
      return c.html(renderMcpHostConsentExpiredPage(), 400);
    }
    try {
      client = await persistMcpHostOauthClientMetadataDocument(client);
    } catch {
      client = null;
    }
    if (!client) return c.html(renderMcpHostConsentExpiredPage(), 400);
  }

  if (!profile.scopesSupported(pending.scopes)) {
    return c.text("invalid_scope", 400);
  }
  const scopes = normalizeMcpHostScopes(pending.scopes);
  await upsertMcpHostOauthGrant({
    clientId: pending.clientId,
    userId: user.id,
    scopes,
  });

  const code = await createMcpHostAuthorizationCode({
    clientId: pending.clientId,
    userId: user.id,
    redirectUri: pending.redirectUri,
    scopes,
    resource: pending.resource,
    codeChallenge: pending.codeChallenge,
    codeChallengeMethod: pending.codeChallengeMethod,
    expiresAt: new Date(Date.now() + MCP_HOST_AUTHORIZATION_CODE_TTL_SECONDS * 1000),
  });

  return c.redirect(
    redirectWithCode(
      pending.redirectUri,
      code,
      (profile.endpoints ?? mcpHostOAuthEndpoints)(c).issuer,
      pending.state,
    ),
  );
}

import { describe, expect, test } from "vitest";
import { redirectWithCode, redirectWithOAuthError } from "./authorize";

describe("MCP Host OAuth authorization responses", () => {
  const issuer = "https://genesis.example.com/api/mcp-host/oauth";

  test("binds successful authorization responses to the issuer", () => {
    const response = new URL(
      redirectWithCode("http://127.0.0.1:3210/callback", "code-1", issuer, "state-1"),
    );
    expect(response.searchParams.get("code")).toBe("code-1");
    expect(response.searchParams.get("state")).toBe("state-1");
    expect(response.searchParams.get("iss")).toBe(issuer);
  });

  test("binds error authorization responses to the issuer", () => {
    const response = new URL(
      redirectWithOAuthError("http://127.0.0.1:3210/callback", "access_denied", issuer, "state-2"),
    );
    expect(response.searchParams.get("error")).toBe("access_denied");
    expect(response.searchParams.get("state")).toBe("state-2");
    expect(response.searchParams.get("iss")).toBe(issuer);
  });
});

import type { Context } from "hono";
import type { Env } from "../../types/hono-env";
import { MCP_HOST_ALL_SCOPES } from "../scopes";
import { mcpHostOAuthEndpoints } from "./urls";

type McpOauthEndpoints = ReturnType<typeof mcpHostOAuthEndpoints>;

export function handleProtectedResourceMetadata(
  c: Context<Env>,
  options?: { endpoints: (c: Context<Env>) => McpOauthEndpoints; scopes: readonly string[] },
) {
  const endpoints = (options?.endpoints ?? mcpHostOAuthEndpoints)(c);
  return c.json({
    resource: endpoints.resourceUri,
    authorization_servers: [endpoints.issuer],
    bearer_methods_supported: ["header"],
    scopes_supported: [...(options?.scopes ?? MCP_HOST_ALL_SCOPES)],
  });
}

export function handleAuthorizationServerMetadata(
  c: Context<Env>,
  options?: { endpoints: (c: Context<Env>) => McpOauthEndpoints; scopes: readonly string[] },
) {
  const endpoints = (options?.endpoints ?? mcpHostOAuthEndpoints)(c);
  return c.json({
    issuer: endpoints.issuer,
    authorization_endpoint: endpoints.authorizationEndpoint,
    token_endpoint: endpoints.tokenEndpoint,
    registration_endpoint: endpoints.registrationEndpoint,
    response_types_supported: ["code"],
    grant_types_supported: ["authorization_code", "refresh_token"],
    code_challenge_methods_supported: ["S256"],
    token_endpoint_auth_methods_supported: ["none", "client_secret_post"],
    authorization_response_iss_parameter_supported: true,
    client_id_metadata_document_supported: true,
    scopes_supported: [...(options?.scopes ?? MCP_HOST_ALL_SCOPES)],
  });
}

import { getDefaultAppBaseUrl } from "../lib/server-urls";

export const MCP_HOST_OAUTH_PATH = "/mcp-host/oauth";
export const MCP_HOST_RESOURCE_PATH = "/mcp";
export const OPS_MCP_OAUTH_PATH = "/mcp-host/ops";
export const OPS_MCP_RESOURCE_PATH = "/mcp/ops";

export function isMcpHostDisabled(): boolean {
  return process.env.GENESIS_MCP_HOST_DISABLED?.trim() === "1";
}

export function mcpHostIssuerBaseUrl(baseUrl: string): string {
  return `${baseUrl.replace(/\/$/, "")}/api${MCP_HOST_OAUTH_PATH}`;
}

export function mcpHostResourceUri(baseUrl: string): string {
  return `${baseUrl.replace(/\/$/, "")}/api${MCP_HOST_RESOURCE_PATH}`;
}

export function opsMcpResourceUri(baseUrl: string): string {
  return (
    process.env.OPS_MCP_RESOURCE_URL?.trim() ||
    `${baseUrl.replace(/\/$/, "")}/api${OPS_MCP_RESOURCE_PATH}`
  ).replace(/\/$/, "");
}

export function resolveMcpHostBaseUrl(configured?: string | null): string {
  return (configured?.trim() || getDefaultAppBaseUrl()).replace(/\/$/, "");
}

function positiveIntEnv(name: string, fallback: number): number {
  const raw = process.env[name]?.trim();
  if (!raw) return fallback;
  const parsed = Number.parseInt(raw, 10);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
}

export const MCP_HOST_ACCESS_TOKEN_TTL_SECONDS = positiveIntEnv(
  "GENESIS_MCP_HOST_ACCESS_TOKEN_TTL_SECONDS",
  3600,
);
export const MCP_HOST_REFRESH_TOKEN_TTL_SECONDS = positiveIntEnv(
  "GENESIS_MCP_HOST_REFRESH_TOKEN_TTL_SECONDS",
  60 * 60 * 24 * 30,
);
export const MCP_HOST_AUTHORIZATION_CODE_TTL_SECONDS = 300;

export const MCP_HOST_CLIENT_ID_PREFIX = "mcphost_";

