import { type Context, Hono } from "hono";
import { authMiddleware, optionalAuthMiddleware } from "../../lib/auth";
import { isMcpHostDisabled, OPS_MCP_OAUTH_PATH, opsMcpResourceUri } from "../../mcp-host/config";
import type { McpOauthResourceProfile } from "../../mcp-host/oauth/authorize";
import {
  handleMcpHostOauthAuthorize,
  handleMcpHostOauthConsent,
} from "../../mcp-host/oauth/authorize";
import { mcpJwtJwks } from "../../mcp-host/oauth/jwt";
import {
  handleAuthorizationServerMetadata,
  handleProtectedResourceMetadata,
} from "../../mcp-host/oauth/metadata";
import { handleMcpHostOauthRegister } from "../../mcp-host/oauth/register";
import { handleMcpHostOauthToken } from "../../mcp-host/oauth/token";
import { opsMcpOAuthEndpoints } from "../../mcp-host/oauth/urls";
import { publicMcpCors } from "../../mcp-host/public-cors";
import { handleMcpHostResourceRequest } from "../../mcp-host/resource/handler";
import {
  areOpsMcpScopesSupported,
  OPS_MCP_ALL_SCOPES,
  OPS_MCP_DEFAULT_SCOPES,
} from "../../mcp-host/scopes";
import type { Env } from "../../types/hono-env";

function mcpHostUnavailable(c: Context<Env>) {
  return c.text("MCP Host disabled", 503);
}

function opsMcpIssuerUnavailable(c: Context<Env>) {
  return c.text("Ops MCP issuer unavailable", 503);
}

function isOpsMcpIssuerEnabled(): boolean {
  return process.env.OPS_MCP_ISSUER_ENABLED?.trim() === "1";
}

const opsMcpProfile = {
  resourceUri: opsMcpResourceUri,
  defaultScopes: OPS_MCP_DEFAULT_SCOPES,
  scopesSupported: areOpsMcpScopesSupported,
  employeeOnly: true,
  consentActionPath: `/api${OPS_MCP_OAUTH_PATH}/consent`,
  jwtAccessTokens: true,
  endpoints: opsMcpOAuthEndpoints,
} satisfies McpOauthResourceProfile;

const mcpHostRoutes = new Hono<Env>()
  .use("/.well-known/*", publicMcpCors)
  .use("/mcp/.well-known/*", publicMcpCors)
  .use("/mcp-host/oauth/.well-known/*", publicMcpCors)
  .use("/mcp-host/oauth/register", publicMcpCors)
  .use("/mcp-host/oauth/token", publicMcpCors)
  .use("/mcp-host/ops/.well-known/*", publicMcpCors)
  .use("/mcp-host/ops/jwks.json", publicMcpCors)
  .use("/mcp-host/ops/token", publicMcpCors)
  .use("/mcp", publicMcpCors)
  // Browser-based public clients exchange PKCE codes directly. The token
  // endpoint does not use cookies; the one-time code and verifier are its
  // credentials, so a wildcard response origin is safe and interoperable.
  .get("/.well-known/oauth-protected-resource", (c) =>
    isMcpHostDisabled() ? mcpHostUnavailable(c) : handleProtectedResourceMetadata(c),
  )
  .get("/.well-known/oauth-authorization-server", (c) =>
    isMcpHostDisabled() ? mcpHostUnavailable(c) : handleAuthorizationServerMetadata(c),
  )
  .get("/mcp/.well-known/oauth-protected-resource", (c) =>
    isMcpHostDisabled() ? mcpHostUnavailable(c) : handleProtectedResourceMetadata(c),
  )
  // Scanners and some clients probe AS metadata next to the MCP resource path.
  .get("/mcp/.well-known/oauth-authorization-server", (c) =>
    isMcpHostDisabled() ? mcpHostUnavailable(c) : handleAuthorizationServerMetadata(c),
  )
  .get("/mcp/.well-known/openid-configuration", (c) =>
    isMcpHostDisabled() ? mcpHostUnavailable(c) : handleAuthorizationServerMetadata(c),
  )
  .get("/mcp-host/oauth/.well-known/oauth-authorization-server", (c) =>
    isMcpHostDisabled() ? mcpHostUnavailable(c) : handleAuthorizationServerMetadata(c),
  )
  .get("/mcp-host/oauth/.well-known/openid-configuration", (c) =>
    isMcpHostDisabled() ? mcpHostUnavailable(c) : handleAuthorizationServerMetadata(c),
  )
  .get("/mcp-host/ops/.well-known/oauth-authorization-server", (c) =>
    isMcpHostDisabled() || !isOpsMcpIssuerEnabled()
      ? opsMcpIssuerUnavailable(c)
      : handleAuthorizationServerMetadata(c, {
          endpoints: opsMcpOAuthEndpoints,
          scopes: OPS_MCP_ALL_SCOPES,
        }),
  )
  .get("/mcp-host/ops/.well-known/openid-configuration", (c) =>
    isMcpHostDisabled() || !isOpsMcpIssuerEnabled()
      ? opsMcpIssuerUnavailable(c)
      : handleAuthorizationServerMetadata(c, {
          endpoints: opsMcpOAuthEndpoints,
          scopes: OPS_MCP_ALL_SCOPES,
        }),
  )
  .get("/mcp-host/ops/jwks.json", (c) =>
    !isMcpHostDisabled() && isOpsMcpIssuerEnabled()
      ? c.json(mcpJwtJwks())
      : opsMcpIssuerUnavailable(c),
  )
  .post("/mcp-host/oauth/register", (c) =>
    isMcpHostDisabled() ? mcpHostUnavailable(c) : handleMcpHostOauthRegister(c),
  )
  .post("/mcp-host/oauth/token", (c) =>
    isMcpHostDisabled() ? mcpHostUnavailable(c) : handleMcpHostOauthToken(c),
  )
  .post("/mcp-host/ops/token", (c) =>
    isMcpHostDisabled() || !isOpsMcpIssuerEnabled()
      ? opsMcpIssuerUnavailable(c)
      : handleMcpHostOauthToken(c, opsMcpProfile),
  )
  .get("/mcp-host/oauth/authorize", optionalAuthMiddleware, async (c) => {
    if (isMcpHostDisabled()) return mcpHostUnavailable(c);
    let user = null;
    try {
      user = await c.var.auth.getUser();
    } catch {
      user = null;
    }
    return handleMcpHostOauthAuthorize(c, user);
  })
  .post("/mcp-host/oauth/consent", authMiddleware, async (c) => {
    if (isMcpHostDisabled()) return mcpHostUnavailable(c);
    const user = await c.var.auth.getUser();
    return handleMcpHostOauthConsent(c, user);
  })
  .get("/mcp-host/ops/authorize", optionalAuthMiddleware, async (c) => {
    if (isMcpHostDisabled() || !isOpsMcpIssuerEnabled()) return opsMcpIssuerUnavailable(c);
    let user = null;
    try {
      user = await c.var.auth.getUser();
    } catch {
      user = null;
    }
    return handleMcpHostOauthAuthorize(c, user, opsMcpProfile);
  })
  .post("/mcp-host/ops/consent", authMiddleware, async (c) => {
    if (isMcpHostDisabled() || !isOpsMcpIssuerEnabled()) return opsMcpIssuerUnavailable(c);
    return handleMcpHostOauthConsent(c, await c.var.auth.getUser(), opsMcpProfile);
  })
  .all("/mcp", (c) =>
    isMcpHostDisabled() ? mcpHostUnavailable(c) : handleMcpHostResourceRequest(c),
  );

export default mcpHostRoutes;

import type { Context } from "hono";
import { getAppBaseUrl } from "../../lib/server-urls";
import type { Env } from "../../types/hono-env";
import {
  MCP_HOST_OAUTH_PATH,
  MCP_HOST_RESOURCE_PATH,
  mcpHostIssuerBaseUrl,
  mcpHostResourceUri,
  OPS_MCP_OAUTH_PATH,
  OPS_MCP_RESOURCE_PATH,
  opsMcpResourceUri,
} from "../config";
import { MCP_HOST_DEFAULT_SCOPES } from "../scopes";

export function mcpHostApiBaseUrl(c: Context<Env>): string {
  return getAppBaseUrl(c);
}

/**
 * Same-process realtime endpoint for MCP-initiated missions.
 *
 * The MCP request is already executing in the Bun process that owns `/api/ws`.
 * Looping back to that listener avoids a needless trip through the public
 * proxy while preserving the existing realtime authentication, authorization,
 * command, and distributed session-routing path.
 */
export function mcpHostRealtimeWebSocketUrl(_c: Context<Env>): string {
  const port = Number(process.env.PORT ?? 3000);
  if (!Number.isInteger(port) || port < 1 || port > 65_535) {
    throw new Error("Genesis server PORT must be an integer between 1 and 65535.");
  }
  return `ws://127.0.0.1:${port}/api/ws`;
}

export function mcpHostResourceMetadataUrl(c: Context<Env>): string {
  return `${mcpHostResourceUri(mcpHostApiBaseUrl(c))}/.well-known/oauth-protected-resource`;
}

export function mcpHostAuthorizationServerMetadataUrl(c: Context<Env>): string {
  return `${mcpHostIssuerBaseUrl(mcpHostApiBaseUrl(c))}/.well-known/oauth-authorization-server`;
}

export function mcpHostOAuthEndpoints(c: Context<Env>) {
  const baseUrl = mcpHostApiBaseUrl(c);
  const issuer = mcpHostIssuerBaseUrl(baseUrl);
  return {
    issuer,
    authorizationEndpoint: `${issuer}/authorize`,
    tokenEndpoint: `${issuer}/token`,
    registrationEndpoint: `${issuer}/register`,
    resourceUri: mcpHostResourceUri(baseUrl),
    resourcePath: MCP_HOST_RESOURCE_PATH,
    oauthPath: MCP_HOST_OAUTH_PATH,
  };
}

export function opsMcpOAuthEndpoints(c: Context<Env>) {
  const baseUrl = mcpHostApiBaseUrl(c);
  const issuer = `${baseUrl}/api${OPS_MCP_OAUTH_PATH}`;
  return {
    issuer,
    authorizationEndpoint: `${issuer}/authorize`,
    tokenEndpoint: `${issuer}/token`,
    registrationEndpoint: `${baseUrl}/api${MCP_HOST_OAUTH_PATH}/register`,
    resourceUri: opsMcpResourceUri(baseUrl),
    resourcePath: OPS_MCP_RESOURCE_PATH,
    oauthPath: OPS_MCP_OAUTH_PATH,
  };
}

export function buildMcpHostWwwAuthenticateHeader(c: Context<Env>): string {
  const metadataUrl = mcpHostResourceMetadataUrl(c);
  // MCP authorization SHOULD include scope on the challenge so clients pick
  // least-privilege scopes without reading scopes_supported first.
  const scope = MCP_HOST_DEFAULT_SCOPES.join(" ");
  return `Bearer realm="genesis-mcp-host", resource_metadata="${metadataUrl}", scope="${scope}"`;
}

